def compact(c):
 return {'duration':sum(f['durationMs']for f in c['frames']),'frames':[{'png':rel(f['png']),'body':rel(f['layers']['body']['png'])if'body'in f.get('layers',{})else rel(f['png']),'duration':f['durationMs'],'phase':f['phase'],'joints':f.get('manualJointsNative')}for f in c['frames']]}
for k,cfg in plan['clips'].items():
 cp=Path(cfg['dest'])/'clip.json';c=load(cp);old=load(c['sourceParentClip']);mp=swordMap if k=='Sword'else axeMap
