 frontcs={n:load(path)for n,path in fronts.items()};matches=[]
 for i,f in enumerate(c['frames']):
  phase=mp[f['phase']];refs={n:next(j for j,z in enumerate(fc['frames'])if z['phase']==phase)for n,fc in frontcs.items()};f['frontalPhaseReference']={n:{'clip':fronts[n],'clipSha256':sha(fronts[n]),'frame':refs[n],'phase':phase,'durationMs':frontcs[n]['frames'][refs[n]]['durationMs']}for n in fronts};matches.append({'index':i,'phase':f['phase'],'durationMs':f['durationMs'],'frontalPhase':phase,'frontalFrames':refs})
 cp.write_text(json.dumps(c,indent=2),encoding='utf-8')
 mapping[k]={'candidateMs':c['totalDurationMs'],'frontals':{n:{'clip':fronts[n],'sha256':sha(fronts[n]),'durationMs':fc['totalDurationMs']}for n,fc in frontcs.items()},'phases':matches}
 data[k]={'candidate':compact(c),'before':compact(old),'front_l':compact(frontcs['front_l']),'front_r':compact(frontcs['front_r']),'phaseMaps':{'before':oldS if k=='Sword'else oldA,'front_l':[a['frontalFrames']['front_l']for a in matches],'front_r':[a['frontalFrames']['front_r']for a in matches]},'roi':json.loads((E/'bookend-flash-audit.json').read_text())[k]}
