html='''<!doctype html><meta charset="utf-8"><title>Orc V1 — back_l manual V7</title><style>body{margin:24px;background:#1a1e25;color:#dde4ed;font:16px system-ui}a{color:#9aceff}header{position:sticky;top:0;z-index:4;background:#1a1e25;padding:8px;border-bottom:1px solid #434d5b}button,select,input{margin:5px;padding:7px}section{display:flex;gap:18px;flex-wrap:wrap;margin:20px 0}article{background:#282f3a;padding:12px;max-width:100%;overflow:auto}h3{font-size:17px;margin:4px 0 12px}canvas,img{image-rendering:pixelated;background:repeating-conic-gradient(#343c48 0% 25%,#2d3440 0% 50%) 50%/16px 16px}canvas{width:256px;height:256px}table{border-collapse:collapse;font-size:14px}td,th{padding:8px;border:1px solid #4b5666}p{max-width:1150px}.meta{font-size:13px;color:#b7c3d3;max-width:440px}.shoulder img{max-width:100%;width:832px}.small{font-size:14px;color:#b7c3d3}</style><h1>Orc V1 · back_l · dois ciclos manuais V7</h1><p>V7_BACK_L_FULL_MANUAL_READY · TECHNICALLY_COMPLETE · VISUAL_REVIEW_REQUIRED · PENDING_CREATOR</p><p>Sword: 15 quadros / 860 ms. Axe: 15 quadros / 1.230 ms. Zero geração. Revisão em repetição; os clipes são ações únicas. Alinhar fases mostra os quadros frontais correspondentes; “tempos próprios” reproduz cada clipe com seu tempo real.</p><p><a href="report.md">Relatório</a> · <a href="full-cycle/joint-metrics.json">Juntas</a> · <a href="full-cycle/phase-comparison.json">Comparação de fases</a> · <a href="full-cycle/bookend-flash-audit.json">Ombro/bookends</a> · <a href="pose-stage-preview.html">Chaves anteriores preservadas</a></p><header><select id="kind"><option>Sword</option><option>Axe</option></select><button id="play">Pausar</button><button id="prev">◀ Quadro</button><button id="next">Quadro ▶</button><select id="speed"><option value="1">1× normal</option><option value="0.5">0,5× lenta</option></select><select id="zoom"><option value="1">1× · corpo128</option><option value="0.5">Tático · corpo64</option><option value="2">Zoom 2×</option><option value="3">Zoom 3×</option></select><select id="sync"><option value="phase">Alinhar fases</option><option value="own">Tempos próprios</option></select><label><input type="checkbox" id="body">body-only</label><label><input type="checkbox" id="joints">juntas</label><label><input type="checkbox" id="repeat" checked>repetir revisão</label><button id="return">Ver retorno</button><br><input id="frame" type="range" min="0" max="14" value="0"><span id="state"></span></header><section id="views"></section><h2>Retorno e ombro esquerdo</h2><p>Recorte nativo x35..60 / y25..52, ampliado 8× no Aseprite. Antes: V6 F10 → F11 → F00 → F01. Depois: manual F12 → F14 → F00 → F01. Primeiro/último corpo manual são idênticos; a região do ombro não muda na entrada ou saída imediatas.</p><section class="shoulder"><article><h3>Antes · V6</h3><img id="bookBefore"></article><article><h3>Depois · manual</h3><img id="bookAfter"></article></section><div id="shoulderStats"></div><h2>Juntas e fases do ciclo</h2><div id="phaseTable"></div><h2>Ampliações de ápice, descida e impacto</h2><section id="details"></section><script>const data=DATA;let kind='Sword',playing=true,elapsed=0,last=0,rate=1,zoom=1,body=false,joints=false;const cache={},views=[];for(const pack of Object.values(data))for(const role of ['before','candidate','front_l','front_r'])for(const f of pack[role].frames)for(const key of ['png','body'])if(!cache[f[key]]){const im=new Image();im.dataset.url=f[key];cache[f[key]]=im}for(const [role,title]of[['before','Antes · V6 rejeitado'],['candidate','Depois · back_l manual'],['front_l','Frontal front_l · referência'],['front_r','Frontal front_r · referência']]){const a=document.createElement('article');a.innerHTML='<h3>'+title+'</h3>';const c=document.createElement('canvas');c.width=c.height=256;c.dataset.role=role;a.append(c);const label=document.createElement('p');label.className='meta';a.append(label);document.querySelector('#views').append(a);views.push({role,c,label})}window.ready=(async()=>{const all=Object.values(cache);for(let i=0;i<all.length;i+=6)await Promise.all(all.slice(i,i+6).map(im=>{im.src=im.dataset.url;return im.decode()}))})().then(()=>{window.loaded=true;updateInfo();draw()});function frameAt(pack,t,repeat){let time=repeat?t%pack.duration:Math.min(t,pack.duration-.001);for(let i=0;i<pack.frames.length;i++){if(time<pack.frames[i].duration)return i;time-=pack.frames[i].duration}return pack.frames.length-1}function index(){return frameAt(data[kind].candidate,elapsed,document.querySelector('#repeat').checked)}function draw(){if(!window.loaded)return;const pack=data[kind],ci=index(),phase=document.querySelector('#sync').value==='phase';for(const v of views){const i=v.role==='candidate'?ci:(phase?pack.phaseMaps[v.role][ci]:frameAt(pack[v.role],elapsed,document.querySelector('#repeat').checked));const f=pack[v.role].frames[i],url=f[body?'body':'png'],ctx=v.c.getContext('2d');ctx.clearRect(0,0,256,256);ctx.imageSmoothingEnabled=false;ctx.drawImage(cache[url],0,0);if(joints&&v.role==='candidate'&&f.joints){const j=f.joints;ctx.lineWidth=1;ctx.strokeStyle='#ffbd4b';ctx.beginPath();ctx.moveTo(j.shoulder[0]+64,j.shoulder[1]+64);ctx.lineTo(j.elbow[0]+64,j.elbow[1]+64);ctx.lineTo(j.wrist[0]+64,j.wrist[1]+64);ctx.lineTo(j.palm[0]+64,j.palm[1]+64);ctx.stroke();for(const p of Object.values(j)){ctx.fillStyle='#6ee5ff';ctx.fillRect(p[0]+63,p[1]+63,3,3)}}v.c.style.width=v.c.style.height=256*zoom+'px';v.c.dataset.frame=i;v.c.dataset.source=url;v.label.textContent='F'+String(i).padStart(2,'0')+' · '+f.phase+' · '+f.duration+' ms'+(phase&&v.role.startsWith('front')?' · referência alinhada por fase':'')}document.querySelector('#frame').value=ci;document.querySelector('#state').textContent=kind+' F'+String(ci).padStart(2,'0')+' · '+pack.candidate.frames[ci].phase+' · '+pack.candidate.duration+' ms'}function setFrame(i){playing=false;document.querySelector('#play').textContent='Reproduzir';const f=data[kind].candidate.frames;i=(i+f.length)%f.length;elapsed=f.slice(0,i).reduce((a,v)=>a+v.duration,0);draw()}function updateInfo(){const p=data[kind],f=p.roi,k=kind.toLowerCase();document.querySelector('#bookBefore').src='full-cycle/'+k+'-bookend-before.png';document.querySelector('#bookAfter').src='full-cycle/'+k+'-bookend-after.png';document.querySelector('#shoulderStats').innerHTML='<p class="small">V6: '+f.oldFrame00.brightNeutralPixels145+' pixels neutros claros no ombro do bookend; ataque adjacente: '+f.oldFrame01.brightNeutralPixels145+'. Manual: ombro igual entre F00/F01 e F13/F14; corpo F14→F00: 0 pixels divergentes. Não é declaração de ausência universal de flicker artístico.</p>';document.querySelector('#phaseTable').innerHTML='<table><tr><th>F</th><th>Fase</th><th>ms</th><th>Ombro</th><th>Cotovelo</th><th>Punho</th><th>Palma</th><th>Frontal F</th></tr>'+p.candidate.frames.map((a,i)=>'<tr><td>'+i+'</td><td>'+a.phase+'</td><td>'+a.duration+'</td>'+['shoulder','elbow','wrist','palm'].map(n=>'<td>'+a.joints[n]+'</td>').join('')+'<td>'+p.phaseMaps.front_l[i]+'</td></tr>').join('')+'</table>';document.querySelector('#details').innerHTML=[6,7,8,9].map(i=>'<article><h3>F'+String(i).padStart(2,'0')+' · '+p.candidate.frames[i].phase+'</h3><a href="full-cycle/'+k+'-'+String(i).padStart(2,'0')+'-large.png"><img src="full-cycle/'+k+'-'+String(i).padStart(2,'0')+'-large.png" width="384"></a></article>').join('')}
document.querySelector('#kind').onchange=e=>{kind=e.target.value;elapsed=0;updateInfo();draw()};document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pausar':'Reproduzir';if(playing&&elapsed>=data[kind].candidate.duration-.01)elapsed=0};document.querySelector('#prev').onclick=()=>setFrame(index()-1);document.querySelector('#next').onclick=()=>setFrame(index()+1);document.querySelector('#frame').oninput=e=>setFrame(+e.target.value);document.querySelector('#speed').onchange=e=>rate=+e.target.value;document.querySelector('#zoom').onchange=e=>{zoom=+e.target.value;draw()};document.querySelector('#body').onchange=e=>{body=e.target.checked;draw()};document.querySelector('#joints').onchange=e=>{joints=e.target.checked;draw()};document.querySelector('#sync').onchange=draw;document.querySelector('#repeat').onchange=draw;document.querySelector('#return').onclick=()=>{setFrame(12);playing=true;document.querySelector('#repeat').checked=true;document.querySelector('#play').textContent='Pausar'};function tick(t){const dt=last?Math.min(t-last,100):0;last=t;if(playing&&window.loaded){elapsed+=dt*rate;if(!document.querySelector('#repeat').checked&&elapsed>=data[kind].candidate.duration){elapsed=data[kind].candidate.duration-.001;playing=false;document.querySelector('#play').textContent='Reproduzir'}draw()}requestAnimationFrame(tick)}requestAnimationFrame(tick);</script>'''
